/// <summary>
/// clean up table for anything older than 14 days
/// </summary>
internal static void cleanUpPricingTopPickingQueue()
{
    utcdatetime cutOffDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -14);

    METPEPricingTopPickingQueue pricingTopPickingQueue;
    METPEPricingTopPickingQueue::skip(pricingTopPickingQueue);

    ttsbegin;
    delete_from pricingTopPickingQueue
        where pricingTopPickingQueue.CreatedDateTime <= cutOffDateTime;
    ttscommit;
}

/// <summary>
/// skip method for performance purpose
/// </summary>
/// <param name = "_postPricingOrderOptimisationQueue"><c>METPostPricingOrderOptimisationQueue</c> record</param>
internal static void skip(METPEPricingTopPickingQueue _pricingTopPickingQueue)
{
    _pricingTopPickingQueue.skipDatabaseLog(true);
    _pricingTopPickingQueue.skipDataMethods(true);
    _pricingTopPickingQueue.skipDeleteActions(true);
    _pricingTopPickingQueue.skipEvents(true);
    _pricingTopPickingQueue.skipBusinessEvents(true);
}
